-- Enchères Animés — character power ratings
--
-- Generated by `npm run ratings` from src/data/rosters.json. Do not edit.
-- Run after 0003_ranking.sql, and again whenever ratings change, so that the
-- server judges ranked games with the same numbers the app shows. The universe
-- of each card is what a ranked mode deals from.

alter table encheres.characters add column if not exists universe text;

on conflict (id) do update set power = excluded.power, universe = excluded.universe;
